#!/usr/bin/env node
/**
 * Baseline check for the browser preset's `lib` choice.
 *
 * Reads the `web-features` dataset (https://npm.im/web-features) as JSON on
 * stdin and writes `baseline-data/browser-lib-status.json` — a snapshot of the
 * Baseline status of marker features for each yearly ES `lib`, plus what that
 * implies for the `lib` in `base-browser-bare.json`.
 *
 * Policy encoded here: the browser preset targets the newest `ES<year>` lib
 * whose marker features are all at least Baseline "newly available"
 * (`baseline: "low"`). `newestWidelyAvailable` is also tracked for reference.
 *
 * Deterministic: output depends only on stdin data + this file + the current
 * tsconfig, so a no-change run produces a byte-identical file (and no PR).
 *
 * Usage (see the `baseline:*` scripts in package.json):
 *   npm install --no-save --ignore-scripts web-features@latest
 *   node .github/scripts/baseline-lib-check.mjs < node_modules/web-features/data.json
 */

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const OUTPUT = join(ROOT, 'baseline-data', 'browser-lib-status.json');
const BROWSER_BASE = join(ROOT, 'base-browser-bare.json');

/**
 * Marker features (web-features IDs) that represent what each yearly ES lib
 * adds. When a new ES edition lands, add a year here and, once TypeScript
 * ships the lib, this script will start recommending it as Baseline matures.
 */
const MARKERS = {
  ES2023: [
    'array-by-copy',
    'array-findlast',
    'hashbang-comments',
  ],
  ES2024: [
    'array-group',
    'atomics-wait-async',
    'promise-withresolvers',
    'resizable-buffers',
    'string-wellformed',
  ],
  ES2025: [
    'float16array',
    'iterator-methods',
    'json-modules',
    'promise-try',
    'regexp-escape',
    'set-methods',
  ],
  ES2026: [
    'array-fromasync',
    'explicit-resource-management',
    'is-error',
    'math-sum-precise',
    'uint8array-base64-hex',
  ],
};

const RANK = new Map([[false, 0], ['low', 1], ['high', 2]]);
const VERDICTS = ['limited-availability', 'newly-available', 'widely-available'];

const raw = readFileSync(0, 'utf8');
const { features } = JSON.parse(raw);

if (!features || typeof features !== 'object') {
  throw new Error('Expected web-features data JSON with a "features" key on stdin');
}

const years = {};

for (const year of Object.keys(MARKERS).sort()) {
  let worst = 2;
  const markerStatus = {};

  for (const id of [...MARKERS[year]].sort()) {
    const feature = features[id];
    if (!feature?.status) {
      throw new Error(`Marker feature "${id}" is missing from the web-features data — has it been renamed upstream?`);
    }
    const { baseline, baseline_low_date: low, baseline_high_date: high } = feature.status;
    if (!RANK.has(baseline)) {
      throw new Error(`Marker feature "${id}" has unexpected baseline value: ${JSON.stringify(baseline)}`);
    }
    worst = Math.min(worst, RANK.get(baseline));
    markerStatus[id] = {
      baseline: VERDICTS[RANK.get(baseline)],
      ...low && { newlyAvailableSince: low },
      ...high && { widelyAvailableSince: high },
    };
  }

  years[year] = { verdict: VERDICTS[worst], features: markerStatus };
}

const yearNames = Object.keys(years);
const newestWhere = minimumRank => {
  // Scan cumulatively: only return a year if ALL years up to and including it meet minimumRank
  let candidate = null;
  for (const year of yearNames) {
    if (VERDICTS.indexOf(years[year].verdict) >= minimumRank) {
      candidate = year;
    } else {
      // Gap found: reset candidate since we can't skip over a non-qualifying year
      candidate = null;
    }
  }
  return candidate;
};

const browserBase = JSON.parse(readFileSync(BROWSER_BASE, 'utf8'));
const currentLib = (browserBase.compilerOptions?.lib || []).find(name => /^ES\d{4}$/.test(name));

if (!currentLib) {
  throw new Error(`Found no ES<year> lib in ${BROWSER_BASE}`);
}

const recommendedLib = newestWhere(1) || currentLib;

const result = {
  '//': 'Generated by .github/scripts/baseline-lib-check.mjs — do not edit by hand',
  currentLib,
  recommendedLib,
  newestNewlyAvailable: newestWhere(1),
  newestWidelyAvailable: newestWhere(2),
  inSyncWithBaseline: currentLib === recommendedLib,
  years,
};

mkdirSync(dirname(OUTPUT), { recursive: true });
writeFileSync(OUTPUT, JSON.stringify(result, undefined, 2) + '\n');

console.error(`Current lib: ${currentLib}, recommended: ${recommendedLib} (newest widely available: ${result.newestWidelyAvailable})`);
console.error(`Wrote ${OUTPUT}`);
